query:
-- 1. Remover a constraint UNIQUE global do slug
ALTER TABLE empresas DROP INDEX slug;

-- 2. Adicionar constraint UNIQUE composta por (slug, tenantId)
ALTER TABLE empresas ADD UNIQUE KEY slug_tenant (slug, tenantId);

-- 3. Confirmar a nova estrutura
SHOW INDEX FROM empresas WHERE Key_name = 'slug_tenant';

